from __future__ import annotations
import json, math, hashlib
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
ID = 'agricultural_administration_building'; AUDIT=ROOT/'audit'/f'{ID}_independent_grade_r2'; EVIDENCE=ROOT/'audit'/ID
ASSET=ROOT/'modular'/'buildings'/f'{ID}.blend'
GIS=EVIDENCE/'sources'/'agricultural_administration_gis_feature_267_current.json'; BUILD=EVIDENCE/'build_evidence.json'; PROBE=AUDIT/'blender_probe.json'
def directed(a,b): return max(min(math.dist(p,q) for q in b) for p in a)
def evaluate():
    ev=json.loads(BUILD.read_text(encoding='utf-8')); gd=json.loads(GIS.read_text(encoding='utf-8')); f=next(x for x in gd['features'] if x['attributes'].get('FID')==267); attrs=f['attributes']; ring=[tuple(map(float,p[:2])) for p in f['geometry']['rings'][0][:-1]]
    lat0,lon0=40.4274,-86.9137; xscale=111412.84*math.cos(math.radians(lat0)); world=[((lon-lon0)*xscale,(lat-lat0)*111040.) for lon,lat in ring]
    twice=sum(world[i][0]*world[(i+1)%len(world)][1]-world[(i+1)%len(world)][0]*world[i][1] for i in range(len(world)))
    cx=sum((world[i][0]+world[(i+1)%len(world)][0])*(world[i][0]*world[(i+1)%len(world)][1]-world[(i+1)%len(world)][0]*world[i][1]) for i in range(len(world)))/(3*twice)
    cy=sum((world[i][1]+world[(i+1)%len(world)][1])*(world[i][0]*world[(i+1)%len(world)][1]-world[(i+1)%len(world)][0]*world[i][1]) for i in range(len(world)))/(3*twice)
    source=[(x-cx,y-cy) for x,y in world]; probe=json.loads(PROBE.read_text(encoding='utf-8')); actual=[tuple(p) for p in probe['shell_bottom_unique_vertices_xy_m']]
    dist=max(directed(source,actual),directed(actual,source)); sb=[min(p[0] for p in source),min(p[1] for p in source),max(p[0] for p in source),max(p[1] for p in source)]; mb=[min(p[0] for p in actual),min(p[1] for p in actual),max(p[0] for p in actual),max(p[1] for p in actual)]; be=max(abs(a-b) for a,b in zip(sb,mb))
    m=json.loads((ROOT/'modular'/'manifest.json').read_text(encoding='utf-8')); item=next(a for a in m['assets'] if a.get('id')==ID); origin=item.get('placement_origin_xy_m'); oe=math.dist([cx,cy],origin); identity=attrs.get('BLDG_ABBR')=='AGAD' and attrs.get('BUILDING_N')=='Agricultural Administration Building' and attrs.get('ADDRESS')=='615 Mitch Daniels Blvd' and attrs.get('OWNER')=='PURDUE'; sha=hashlib.sha256(ASSET.read_bytes()).hexdigest(); assert sha==probe['asset_sha256']
    stale=item.get('object_count')!=probe.get('object_count') or sorted(item.get('objects',[]))!=sorted(probe.get('object_names',[])); export=probe.get('reopened_export_collection') and probe.get('collection')==item.get('collection') and not probe.get('external_image_dependencies')
    criteria=[
    {'name':'Correct identity and source-backed footprint','score':2.0 if identity and dist<.01 else 0.0,'max_score':2.0,'evidence':[f'Purdue GIS Feature 267 matches AGAD, full building name, address, and owner PURDUE. Actual reopened shell is {len(actual)} unique base vertices; symmetric Hausdorff error against raw ring is {dist:.6f} m.']},
    {'name':'Position, orientation, and scale/dimensions','score':2.0 if oe<.01 and be<.01 and item.get('local_coordinates') else 0.0,'max_score':2.0,'evidence':[f'Computed GIS centroid ({cx:.6f}, {cy:.6f}) m matches manifest placement origin within {oe:.6f} m. GIS and actual shell bounds differ by {be:.6f} m; footprint spans {sb[2]-sb[0]:.3f} x {sb[3]-sb[1]:.3f} m.']},
    {'name':'Evidence-backed height, floors, and roof form','score':0.75,'max_score':2.0,'evidence':[f'GIS NUM_LEVELS={attrs.get("NUM_LEVELS")} and CountOfFLO={attrs.get("CountOfFLO")} support five levels. Modeled 17.2 m height/floor spacing are explicitly estimates; Extrution={attrs.get("Extrution")} has no documented unit or measurement definition. Current flat roof is unverified; archival photo depicts an earlier roof form.']},
    {'name':'Facade, entrances, and distinctive architecture','score':1.25,'max_score':2.0,'evidence':['Purdue Stories current entrance photo corroborates dark red brick, pale limestone base/bands, repeated windows, and glazed accessible entry; archival image supports historic brick and stone vocabulary.','Model renders reproduce brick, limestone bands/plinth, and repeated bays. Entry is a simple door proxy without the source photo’s tall glazed composition; exact entry location, bays, and dimensions are estimates.']},
    {'name':'Modular export, portability, and evidence completeness','score':1.5 if export else 0.0,'max_score':2.0,'evidence':[f'Independent Blender process reopened the saved .blend, exported only {probe.get("collection")} and reopened the export with {probe.get("object_count")} objects and no external image dependencies.',f'Evidence folder contains raw GIS, two Purdue photo snapshots, source provenance, renders, and uncertainty notes. Shared manifest object names/count remain stale ({item.get("object_count")} vs {probe.get("object_count")}); coordinator must refresh them.']}]
    score=round(sum(c['score'] for c in criteria),2)
    return {'building_id':ID,'score':score,'max_score':10,'pass_threshold':8,'passed':score>=8,'criteria':criteria,'evidence':{'gis_feature_id':attrs.get('FID'),'source_ring_vertices':len(source),'reopened_shell_vertices':len(actual),'symmetric_hausdorff_error_m':dist,'source_local_bounds_m':sb,'model_local_bounds_m':mb,'bounds_error_m':be,'gis_centroid_xy_m':[cx,cy],'manifest_placement_origin_xy_m':origin,'placement_origin_error_m':oe,'model_height_m':probe['shell_bounds_local_m'][2][1],'gis_num_levels':attrs.get('NUM_LEVELS'),'gis_extrution_attribute':attrs.get('Extrution'),'manifest_object_count':item.get('object_count'),'actual_collection_object_count':probe.get('object_count'),'manifest_object_names_stale':stale,'external_image_dependencies':probe.get('external_image_dependencies'),'asset_sha256':sha,'blender_probe':'audit/agricultural_administration_building_independent_grade_r2/blender_probe.py'},'findings':['PASS: source identity and all 24 GIS footprint vertices match the actual shell.','PASS: local centroid, plan bounds, and orientation align with the manifest placement contract.','LIMITATION: no current measured height or roof evidence; 17.2 m is estimated and GIS extrusion units are undocumented.','LIMITATION: photos support materials and entry character, while entrance proxy and fenestration dimensions remain approximate.','INTEGRATION: shared manifest count/names (1,338 vs 6) are stale and need coordinator refresh.']}
if __name__=='__main__':
    result=evaluate(); (AUDIT/'result.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8'); print(json.dumps(result,indent=2,ensure_ascii=False))
